import selectionsJson from "./selections.json";
import playersJson from "./players.json";
import insightsJson from "./insights.json";
import metaJson from "./meta.json";
import type { DatasetMeta, Insights, Player, Role, Selection, Selections, TeamId, TeamInfo } from "../types";

/** Generated by scripts/build_data.py. Selections are the user's approved lists, in approved order. */
export const selections = selectionsJson as Selections;
export const players = playersJson as unknown as Record<string, Player>;
export const insights = insightsJson as Insights;
export const meta = metaJson as DatasetMeta;

export const TEAMS: Record<TeamId, TeamInfo> = {
  team01: {
    id: "team01",
    number: "01",
    title: "Performance Leaders",
    description: "Players selected through pressure performance, consistency, and cricket statistics.",
  },
  team02: {
    id: "team02",
    number: "02",
    title: "Auction Prospects",
    description: "A researched selection of potential external player options for Rajasthan Royals IPL 2027.",
  },
};

export const TEAM_ORDER: TeamId[] = ["team01", "team02"];
export const ROLE_ORDER: Role[] = ["batters", "bowlers"];
export const ROLE_LABEL: Record<Role, string> = { batters: "Batters", bowlers: "Bowlers" };

export function getPlayer(id: number): Player {
  const p = players[String(id)];
  if (!p) throw new Error(`No statistics record for player ${id}`);
  return p;
}

export function teamsContaining(playerId: number): TeamId[] {
  return TEAM_ORDER.filter((t) =>
    ROLE_ORDER.some((r) => selections[t][r].some((s) => s.playerId === playerId)),
  );
}

export function findSelection(name: string): { team: TeamId; role: Role; item: Selection } | undefined {
  for (const team of TEAM_ORDER)
    for (const role of ROLE_ORDER) {
      const item = selections[team][role].find((s) => s.name === name);
      if (item) return { team, role, item };
    }
  return undefined;
}
